                    continue
                weight = self.weight(tree[idx], visited, k)
                if weight > max_val:
                    max_val = weight
                    max_idx = idx
            tree[max_idx] += 1
            visited.add(max_idx)

        result = sum(tree)
        if result % k != 0:
            return -1
        else:
            return result // k

    def weight(self, node: int, visited: set, k: int) -> int:
        weight_sum = 0
        current_node = node
        while True:
            if current_node not in visited:
                visited.add(current_node)
                weight_sum += math.gcd(current_node - visited[0], k)
                current_node += 1
            else:
                break

        return weight_sum
