    def dijkstra(self, edges: List[Tuple[int, int, int]], visited: List[bool], node: int, min_path_sum: float, current_path_weight: int):
        visited[node] = True

        for neighbor, weight in edges[node]:
            if not visited[neighbor]:
                self.dijkstra(edges, visited, neighbor, min_path_sum + weight, current_path_weight + weight)
            else:
                if current_path_weight + weight <= min_path_sum:
                    min_path_sum = current_path_weight + weight
                    current_path_weight += weight

